@Test
public void setGetRemove() {
    String key = UUID.randomUUID().toString();
    String stringValue = "stringValue";
    confParamOps.set(DOMAIN, key, stringValue);
    String actualStringValue = confParamOps.get(DOMAIN, key, null, String.class);
    assertEquals(stringValue, actualStringValue);
    Long longValue = 1L;
    confParamOps.set(DOMAIN, key, longValue);
    Long actualLongValue = confParamOps.get(DOMAIN, key, null, Long.class);
    assertEquals(longValue, actualLongValue);
    Double doubleValue = 2.0;
    confParamOps.set(DOMAIN, key, doubleValue);
    Double actualDoubleValue = confParamOps.get(DOMAIN, key, null, Double.class);
    assertEquals(doubleValue, actualDoubleValue);
    Date dateValue = new Date();
    confParamOps.set(DOMAIN, key, dateValue);
    Date actualDateValue = confParamOps.get(DOMAIN, key, null, Date.class);
    assertEquals(dateValue, actualDateValue);
    Boolean booleanValue = true;
    confParamOps.set(DOMAIN, key, booleanValue);
    Boolean actualBooleanValue = confParamOps.get(DOMAIN, key, null, Boolean.class);
    assertEquals(booleanValue, actualBooleanValue);
    List<String> stringValues = new ArrayList<>();
    stringValues.add("stringValue1");
    stringValues.add("stringValue2");
    confParamOps.set(DOMAIN, key, stringValues);
    List<String> actualStringValues = List.of(confParamOps.get(DOMAIN, key, null, String[].class));
    assertEquals(stringValues, actualStringValues);
    confParamOps.remove(DOMAIN, key);
    assertNull(confParamOps.get(DOMAIN, key, null, String.class));
    assertEquals("defaultValue", confParamOps.get(DOMAIN, key, "defaultValue", String.class));
}

@Test
public void crud() {
    String key = UUID.randomUUID().toString();
    domainOps.create(new JPADomain.Builder(key).jdbcDriver("org.h2.Driver").jdbcURL("jdbc:h2:mem:syncopetest;DB_CLOSE_DELAY=-1").dbUsername("sa").dbPassword("").databasePlatform("org.apache.openjpa.jdbc.sql.H2Dictionary").transactionIsolation(JPADomain.TransactionIsolation.TRANSACTION_READ_UNCOMMITTED).adminPassword("password").adminCipherAlgorithm(CipherAlgorithm.BCRYPT).build());
    JPADomain domain = (JPADomain) domainOps.read(key);
    assertEquals(JPADomain.TransactionIsolation.TRANSACTION_READ_UNCOMMITTED, domain.getTransactionIsolation());
    assertEquals("password", domain.getAdminPassword());
    assertEquals(CipherAlgorithm.BCRYPT, domain.getAdminCipherAlgorithm());
    assertEquals(10, domain.getPoolMaxActive());
    assertEquals(2, domain.getPoolMinIdle());
    List<Domain> list = domainOps.list();
    assertNotNull(list);
    assertEquals(domain, list.getFirst());
    try {
        domainOps.create(new JPADomain.Builder(domain.getKey()).build());
        fail();
    } catch (KeymasterException e) {
        assertNotNull(e);
    }
    domainOps.changeAdminPassword(key, "newpassword", CipherAlgorithm.SSHA512);
    domain = (JPADomain) domainOps.read(key);
    assertEquals("newpassword", domain.getAdminPassword());
    assertEquals(CipherAlgorithm.SSHA512, domain.getAdminCipherAlgorithm());
    domainOps.adjustPoolSize(key, 100, 23);
    domain = (JPADomain) domainOps.read(key);
    assertEquals(100, domain.getPoolMaxActive());
    assertEquals(23, domain.getPoolMinIdle());
    domainOps.delete(key);
    list = domainOps.list();
    assertNotNull(list);
    assertTrue(list.isEmpty());
}

