@Test
public void run() {
    List<NetworkService> list = serviceOps.list(NetworkService.Type.CORE);
    assertTrue(list.isEmpty());
    NetworkService core1 = new NetworkService();
    core1.setType(NetworkService.Type.CORE);
    core1.setAddress("http://localhost:9080/syncope/rest");
    serviceOps.register(core1);
    list = serviceOps.list(NetworkService.Type.CORE);
    assertFalse(list.isEmpty());
    assertEquals(1, list.size());
    assertEquals(core1, list.getFirst());
    assertEquals(core1, serviceOps.get(NetworkService.Type.CORE));
    NetworkService core2 = new NetworkService();
    core2.setType(NetworkService.Type.CORE);
    core2.setAddress("http://localhost:9080/syncope/rest");
    assertEquals(core1, core2);
    serviceOps.register(core2);
    list = serviceOps.list(NetworkService.Type.CORE);
    assertFalse(list.isEmpty());
    assertEquals(1, list.size());
    assertEquals(core1, list.getFirst());
    assertEquals(core1, serviceOps.get(NetworkService.Type.CORE));
    serviceOps.unregister(core1);
    list = serviceOps.list(NetworkService.Type.CORE);
    assertTrue(list.isEmpty());
    try {
        serviceOps.get(NetworkService.Type.CORE);
        fail();
    } catch (KeymasterException e) {
        assertNotNull(e);
    }
}

@Test
public void pullFromCSV() {
    CSVPullSpec spec = new CSVPullSpec.Builder(AnyTypeKind.USER.name(), "username").build();
    InputStream csv = getClass().getResourceAsStream("/test1.csv");
    List<ProvisioningReport> results = AuthContextUtils.callAsAdmin(SyncopeConstants.MASTER_DOMAIN, () -> reconciliationLogic.pull(spec, csv));
    assertEquals(2, results.size());
    assertEquals(AnyTypeKind.USER.name(), results.getFirst().getAnyType());
    assertNotNull(results.getFirst().getKey());
    assertEquals("donizetti", results.getFirst().getName());
    assertEquals("donizetti", results.getFirst().getUidValue());
    assertEquals(ResourceOperation.CREATE, results.get(0).getOperation());
    assertEquals(ProvisioningReport.Status.SUCCESS, results.get(0).getStatus());
    AuthContextUtils.runAsAdmin(SyncopeConstants.MASTER_DOMAIN, () -> {
        UserTO donizetti = userLogic.read(results.getFirst().getKey());
        assertNotNull(donizetti);
        assertEquals("Gaetano", donizetti.getPlainAttr("firstname").get().getValues().getFirst());
        assertEquals(1, donizetti.getPlainAttr("loginDate").get().getValues().size());
        UserTO cimarosa = userLogic.read(results.get(1).getKey());
        assertNotNull(cimarosa);
        assertEquals("Domenico Cimarosa", cimarosa.getPlainAttr("fullname").get().getValues().getFirst());
        assertEquals(2, cimarosa.getPlainAttr("loginDate").get().getValues().size());
    });
}

@Test
public void pushToCSV() throws IOException {
    Page<UserTO> search = AuthContextUtils.callAsAdmin(SyncopeConstants.MASTER_DOMAIN, () -> userLogic.search(null, PageRequest.of(0, 100), SyncopeConstants.ROOT_REALM, true, false));
    assertNotNull(search);
    CSVPushSpec spec = new CSVPushSpec.Builder(AnyTypeKind.USER.name()).ignorePaging(true).field("username").field("status").plainAttr("firstname").plainAttr("surname").plainAttr("email").plainAttr("loginDate").build();
    PipedInputStream in = new PipedInputStream();
    PipedOutputStream os = new PipedOutputStream(in);
    List<ProvisioningReport> results = AuthContextUtils.callAsAdmin(SyncopeConstants.MASTER_DOMAIN, () -> reconciliationLogic.push(null, PageRequest.of(0, 1), SyncopeConstants.ROOT_REALM, spec, os));
    assertEquals(search.getTotalElements(), results.size());
    MappingIterator<Map<String, String>> reader = new CsvMapper().readerFor(Map.class).with(CsvSchema.emptySchema().withHeader()).readValues(in);
    for (int i = 0; i < results.size() && reader.hasNext(); i++) {
        Map<String, String> row = reader.next();
        assertEquals(results.get(i).getName(), row.get("username"));
        assertEquals(search.get().filter(user -> row.get("username").equals(user.getUsername())).findFirst().get().getStatus(), row.get("status"));
        switch(row.get("username")) {
            case "rossini" ->
                {
                    assertEquals(spec.getNullValue(), row.get("email"));
                    assertTrue(row.get("loginDate").contains(spec.getArrayElementSeparator()));
                }
            case "verdi" ->
                {
                    assertEquals("verdi@syncope.org", row.get("email"));
                    assertEquals(spec.getNullValue(), row.get("loginDate"));
                }
            case "bellini" ->
                {
                    assertEquals(spec.getNullValue(), row.get("email"));
                    assertFalse(row.get("loginDate").contains(spec.getArrayElementSeparator()));
                }
            default ->
                {
                }
        }
    }
}

@Test
public void updateChangePurpose() {
    ResourceTO ws1 = logic.read("ws-target-resource-1");
    assertNotNull(ws1);
    Mapping ws1NewUMapping = ws1.getProvision(AnyTypeKind.USER.name()).orElseThrow().getMapping();
    // change purpose from NONE to BOTH
    ws1NewUMapping.getItems().stream().filter(itemTO -> "firstname".equals(itemTO.getIntAttrName())).forEach(itemTO -> itemTO.setPurpose(MappingPurpose.BOTH));
    ws1.getProvision(AnyTypeKind.USER.name()).orElseThrow().setMapping(ws1NewUMapping);
    ws1 = logic.update(ws1);
    assertNotNull(ws1);
}

