    logic.create(buildResourceTO("lss"));
    entityManager.flush();
    ResourceTO resource = logic.read("lss");
    assertNull(resource.getProvision(AnyTypeKind.USER.name()).orElseThrow().getSyncToken());
    ResourceLogic resourceLogic = new ResourceLogic(resourceDAO, anyTypeDAO, null, null, null, null, null, connectorManager, null);
    resourceLogic.setLatestSyncToken(resource.getKey(), AnyTypeKind.USER.name());
    entityManager.flush();
    resource = logic.read(resource.getKey());
    assertNotNull(resource.getProvision(AnyTypeKind.USER.name()).orElseThrow().getSyncToken());
}

@Test
public void executeAndExport() throws Exception {
    ReportTO report = logic.read("0062ea9c-924d-4ecf-9961-4492a8cc6d1b");
    assertNotNull(report);
    assertTrue(report.isActive());
    report.getExecutions().forEach(exec -> logic.deleteExecution(exec.getKey()));
    report = logic.read(report.getKey());
    assertTrue(report.getExecutions().isEmpty());
    JobExecutionContext ctx = mock(JobExecutionContext.class);
    when(ctx.getExecutor()).thenReturn("test");
    when(ctx.isDryRun()).thenReturn(false);
    ReportJobDelegate delegate = ApplicationContextProvider.getBeanFactory().createBean(TestReportJobDelegate.class);
    delegate.execute(report.getKey(), ctx);
    report = logic.read(report.getKey());
    assertFalse(report.getExecutions().isEmpty());
    String execKey = report.getExecutions().getFirst().getKey();
    checkExport(execKey);
}

