@Test
public void asGroupOwner() {
    // prepare authentication
    Map<String, Set<String>> entForRealms = new HashMap<>();
    roleDAO.findById(RoleDAO.GROUP_OWNER_ROLE).orElseThrow().getEntitlements().forEach(entitlement -> {
        Set<String> realms = Optional.ofNullable(entForRealms.get(entitlement)).orElseGet(() -> {
            Set<String> r = new HashSet<>();
            entForRealms.put(entitlement, r);
            return r;
        });
        realms.add(RealmUtils.getGroupOwnerRealm(SyncopeConstants.ROOT_REALM, "37d15e4c-cdc1-460b-a591-8505c8133806"));
    });
    Set<SyncopeGrantedAuthority> authorities = new HashSet<>();
    entForRealms.forEach((key, value) -> {
        SyncopeGrantedAuthority authority = new SyncopeGrantedAuthority(key);
        authority.addRealms(value);
        authorities.add(authority);
    });
    UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken(new org.springframework.security.core.userdetails.User("poorGroupOwner", "FAKE_PASSWORD", authorities), "FAKE_PASSWORD", authorities);
    auth.setDetails(new SyncopeAuthenticationDetails(SyncopeConstants.MASTER_DOMAIN, null));
    SecurityContextHolder.getContext().setAuthentication(auth);
    try {
        // test count() and search()
        Set<String> authRealms = RealmUtils.getEffective(AuthContextUtils.getAuthorizations().get(IdRepoEntitlement.GROUP_SEARCH), SyncopeConstants.ROOT_REALM);
        assertEquals(1, searchDAO.count(realmDAO.getRoot(), true, authRealms, groupDAO.getAllMatchingCond(), AnyTypeKind.GROUP));
        List<Group> groups = searchDAO.search(realmDAO.getRoot(), true, authRealms, groupDAO.getAllMatchingCond(), PageRequest.of(0, 10), AnyTypeKind.GROUP);
        assertEquals(1, groups.size());
        assertEquals("37d15e4c-cdc1-460b-a591-8505c8133806", groups.getFirst().getKey());
    } finally {
        SecurityContextHolder.getContext().setAuthentication(null);
    }
}

