    AuthPolicy authnPolicy = buildAndSaveAuthPolicy();
    sp.setAuthPolicy(authnPolicy);
    saml2spDAO.save(sp);
    assertNotNull(sp);
    assertNotNull(sp.getKey());
    long afterCount = saml2spDAO.count();
