@Test
public void membershipWithAttr() {
    UserUR userUR = new UserUR.Builder("1417acbe-cbf6-4277-9372-e75e04f97000").build();
    // add 'obscure' (no membership): works because 'obscure' is from 'other', default class for USER
    userUR.getPlainAttrs().add(new AttrPatch.Builder(new Attr.Builder("obscure").value("testvalue").build()).build());
    // add 'obscure' (via 'additional' membership): that group defines type extension with classes 'other' and 'csv'
    userUR.getMemberships().add(new MembershipUR.Builder("034740a9-fa10-453b-af37-dc7897e98fb1").plainAttr(new Attr.Builder("obscure").value("testvalue2").build()).build());
    dataBinder.update(userDAO.findById(userUR.getKey()).orElseThrow(), userUR);
    User user = userDAO.findById(userUR.getKey()).orElseThrow();
    UMembership newM = user.getMembership("034740a9-fa10-453b-af37-dc7897e98fb1").orElseThrow();
    assertEquals(1, user.getPlainAttrs(newM).size());
    assertNull(user.getPlainAttr("obscure").orElseThrow().getMembership());
    assertEquals(2, user.getPlainAttrs("obscure").size());
    assertTrue(user.getPlainAttrs("obscure").contains(user.getPlainAttr("obscure").orElseThrow()));
    assertTrue(user.getPlainAttrs("obscure").stream().anyMatch(a -> a.getMembership() == null));
    assertTrue(user.getPlainAttrs("obscure").stream().anyMatch(a -> newM.getKey().equals(a.getMembership())));
}

@Test
public void prepareAttrsForUser() {
    User bellini = userDAO.findByUsername("bellini").orElseThrow();
    ExternalResource ldap = resourceDAO.findById("resource-ldap").orElseThrow();
    Provision provision = ldap.getProvisionByAnyType(AnyTypeKind.USER.name()).get();
    assertNotEquals(CipherAlgorithm.AES, bellini.getCipherAlgorithm());
    // 1. with clear-text password
    Pair<String, Set<Attribute>> attrs = mappingManager.prepareAttrsFromAny(bellini, "Password123", true, Boolean.TRUE, ldap, provision);
    assertEquals("bellini", attrs.getLeft());
    assertEquals("uid=bellini,ou=people,o=isp", AttributeUtil.getNameFromAttributes(attrs.getRight()).getNameValue());
    assertEquals("Password123", SecurityUtil.decrypt(AttributeUtil.getPasswordValue(attrs.getRight())));
    // 2. with changePwd == false
    attrs = mappingManager.prepareAttrsFromAny(bellini, "Password123", false, Boolean.TRUE, ldap, provision);
    assertNull(AttributeUtil.getPasswordValue(attrs.getRight()));
    // 3. with no clear-text password but random password generation enabled
    // after SYNCOPE-1751 no password is going to be generated by DefaultMappingManager,
    // but by AbstractPropagationTaskExecutor
    ldap = resourceDAO.save(ldap);
    entityManager.flush();
    attrs = mappingManager.prepareAttrsFromAny(bellini, null, true, Boolean.TRUE, ldap, provision);
    assertNull(AttributeUtil.getPasswordValue(attrs.getRight()));
    // 4. with no clear-text password and random password generation disabled
    resourceDAO.save(ldap);
    entityManager.flush();
    attrs = mappingManager.prepareAttrsFromAny(bellini, null, true, Boolean.TRUE, ldap, provision);
    assertNull(AttributeUtil.getPasswordValue(attrs.getRight()));
    // 5. with no clear-text password, random password generation disabled but AES
    ReflectionTestUtils.setField(bellini, "cipherAlgorithm", CipherAlgorithm.AES);
    bellini.setPassword("newPassword123");
    userDAO.save(bellini);
    entityManager.flush();
    assertEquals(CipherAlgorithm.AES, bellini.getCipherAlgorithm());
    attrs = mappingManager.prepareAttrsFromAny(bellini, null, true, Boolean.TRUE, ldap, provision);
    assertEquals("newPassword123", SecurityUtil.decrypt(AttributeUtil.getPasswordValue(attrs.getRight())));
}

@Test
public void prepareAttrsForLinkedAccount() {
    User vivaldi = userDAO.findByUsername("vivaldi").orElseThrow();
    ExternalResource ldap = resourceDAO.findById("resource-ldap").orElseThrow();
    Provision provision = ldap.getProvisionByAnyType(AnyTypeKind.USER.name()).get();
    LinkedAccount account = entityFactory.newEntity(LinkedAccount.class);
    account.setConnObjectKeyValue("admin");
    account.setResource(ldap);
    account.setOwner(vivaldi);
    account.setSuspended(Boolean.FALSE);
    account.setCipherAlgorithm(CipherAlgorithm.AES);
    account.setPassword("Password321");
    vivaldi.add(account);
    vivaldi = userDAO.save(vivaldi);
    entityManager.flush();
    // 1. with account password and clear-text default password
    Set<Attribute> attrs = mappingManager.prepareAttrsFromLinkedAccount(vivaldi, account, "Password123", true, provision);
    assertEquals("admin", AttributeUtil.getStringValue(AttributeUtil.find("cn", attrs)));
    assertEquals("Password321", SecurityUtil.decrypt(AttributeUtil.getPasswordValue(attrs)));
    assertTrue(AttributeUtil.getBooleanValue(AttributeUtil.find(OperationalAttributes.ENABLE_NAME, attrs)));
    // 2. without account password and clear-text default password
    account.setEncodedPassword(null, null);
    attrs = mappingManager.prepareAttrsFromLinkedAccount(vivaldi, account, "Password123", true, provision);
    assertEquals("Password123", SecurityUtil.decrypt(AttributeUtil.getPasswordValue(attrs)));
    // 3. with changePwd == false
    attrs = mappingManager.prepareAttrsFromLinkedAccount(vivaldi, account, "Password123", false, provision);
    assertNull(AttributeUtil.getPasswordValue(attrs));
    // 4. without account password, no clear-text password but random password generation enabled
    // after SYNCOPE-1751 no password is going to be generated by DefaultMappingManager,
    // but by AbstractPropagationTaskExecutor
    ldap = resourceDAO.save(ldap);
    entityManager.flush();
    attrs = mappingManager.prepareAttrsFromLinkedAccount(vivaldi, account, null, true, provision);
    assertNull(AttributeUtil.getPasswordValue(attrs));
    // 5. without account password, no clear-text password and random password generation disabled
    resourceDAO.save(ldap);
    entityManager.flush();
    attrs = mappingManager.prepareAttrsFromLinkedAccount(vivaldi, account, null, true, provision);
    assertNull(AttributeUtil.getPasswordValue(attrs));
}

