    jobStatusUpdater.initComplete();
    jobStatusUpdater.update(new JobStatusEvent(this, SyncopeConstants.MASTER_DOMAIN, jobName, "Started"));
    assertEquals(JobStatusDAO.UNKNOWN_STATUS, jobStatusDAO.get(jobName));
