    assertTrue(v.verify(JWSHeader.parse(new Base64URL(chunksRSA[0])), (chunksRSA[0] + "." + chunksRSA[1]).getBytes(), new Base64URL(chunksRSA[2])));
    // Verify with EC
    assertTrue(v.verify(JWSHeader.parse(new Base64URL(chunksEC[0])), (chunksEC[0] + "." + chunksEC[1]).getBytes(), new Base64URL(chunksEC[2])));
    Set.of((JWSAlgorithm) jwkRSA.getAlgorithm(), (JWSAlgorithm) jwkEC.getAlgorithm()).forEach(jwsAlgorithm -> assertTrue(v.supportedJWSAlgorithms().contains(jwsAlgorithm)));
    assertDoesNotThrow(v::getJCAContext);
}

