        CONNECTOR_SERVICE.update(connector);
        await().atMost(MAX_WAIT_SECONDS, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).until(() -> {
            try {
                return Files.readString(auditFilePath, StandardCharsets.UTF_8).contains("{\"type\":\"LOGIC\",\"category\":\"ConnectorLogic\",\"subcategory\":null," + "\"op\":\"update\",\"outcome\":\"SUCCESS\"}");
            } catch (Exception e) {
                LOG.error("Could not check content of {}", auditFilePath, e);
                return false;
            }
        });
