    OpEvent updateSuccess = new OpEvent(OpEvent.CategoryType.PROPAGATION, AnyTypeKind.ANY_OBJECT.name(), RESOURCE_NAME_DBSCRIPTED, "update", OpEvent.Outcome.SUCCESS);
    OpEvent updateFailure = new OpEvent(OpEvent.CategoryType.PROPAGATION, AnyTypeKind.ANY_OBJECT.name(), RESOURCE_NAME_DBSCRIPTED, "update", OpEvent.Outcome.FAILURE);
