        fail(e::getMessage);
    } finally {
        try {
            AUDIT_SERVICE.deleteConf(createSuccess.toString());
        } catch (Exception e) {
            // ignore
        }
        try {
            AUDIT_SERVICE.deleteConf(createFailure.toString());
        } catch (Exception e) {
            // ignore
        }
        try {
            AUDIT_SERVICE.deleteConf(updateSuccess.toString());
        } catch (Exception e) {
            // ignore
        }
        try {
            AUDIT_SERVICE.deleteConf(updateFailure.toString());
        } catch (Exception e) {
            // ignore
        }
    }
}

@Test
public void issueSYNCOPE1695() {
    // add audit conf for pull
    AUDIT_SERVICE.setConf(buildAuditConf("[PULL]:[USER]:[resource-ldap]:[matchingrule_update]:[SUCCESS]", true));
    AUDIT_SERVICE.setConf(buildAuditConf("[PULL]:[USER]:[resource-ldap]:[unmatchingrule_assign]:[SUCCESS]", true));
    AUDIT_SERVICE.setConf(buildAuditConf("[PULL]:[USER]:[resource-ldap]:[unmatchingrule_provision]:[SUCCESS]", true));
    UserTO pullFromLDAP = null;
    try {
        // pull from resource-ldap -> generates an audit entry
        PullTaskTO pullTaskTO = new PullTaskTO();
        pullTaskTO.setPerformCreate(true);
        pullTaskTO.setPerformUpdate(true);
        pullTaskTO.getActions().add("LDAPMembershipPullActions");
        pullTaskTO.setDestinationRealm(SyncopeConstants.ROOT_REALM);
        pullTaskTO.setMatchingRule(MatchingRule.UPDATE);
        pullTaskTO.setUnmatchingRule(UnmatchingRule.ASSIGN);
        RECONCILIATION_SERVICE.pull(new ReconQuery.Builder(AnyTypeKind.USER.name(), RESOURCE_NAME_LDAP).fiql("uid==pullFromLDAP").build(), pullTaskTO);
        // update pullTaskTO -> another audit entry
        pullFromLDAP = updateUser(new UserUR.Builder(USER_SERVICE.read("pullFromLDAP").getKey()).plainAttr(new AttrPatch.Builder(new Attr.Builder("ctype").value("abcdef").build()).build()).build()).getEntity();
        // search by empty type and category events and get both events on testfromLDAP
        if (IS_EXT_SEARCH_ENABLED) {
            try {
                Thread.sleep(2000);
            } catch (InterruptedException ex) {
                // ignore
            }
        }
        assertEquals(1, AUDIT_SERVICE.search(new AuditQuery.Builder().entityKey(pullFromLDAP.getKey()).page(1).size(10).outcome(OpEvent.Outcome.SUCCESS).build()).getResult().stream().filter(e -> Set.of("matchingrule_update", "unmatchingrule_assign", "unmatchingrule_provision").contains(e.getOpEvent().getOp())).count());
    } finally {
        if (pullFromLDAP != null) {
            USER_SERVICE.deassociate(new ResourceDR.Builder().key(pullFromLDAP.getKey()).resource(RESOURCE_NAME_LDAP).action(ResourceDeassociationAction.UNLINK).build());
