            // restore previous audit
            AUDIT_SERVICE.setConf(buildAuditConf("[PULL]:[USER]:[resource-ldap]:[matchingrule_update]:[SUCCESS]", false));
            AUDIT_SERVICE.setConf(buildAuditConf("[PULL]:[USER]:[resource-ldap]:[unmatchingrule_assign]:[SUCCESS]", false));
            AUDIT_SERVICE.setConf(buildAuditConf("[PULL]:[USER]:[resource-ldap]:[unmatchingrule_provision]:[SUCCESS]", false));
        }
    }
}

