    createMacroActionsIfNeeded("ProcessBuilderMacroActions", ImplementationEngine.GROOVY, IOUtils.toString(getClass().getResourceAsStream("/ProcessBuilderMacroActions.groovy"), StandardCharsets.UTF_8));
