        fail();
    } catch (WebServiceException e) {
        assertNotNull(e);
    }
    long count = TASK_SERVICE.search(new TaskQuery.Builder(TaskType.PROPAGATION).resource(RESOURCE_NAME_WS1).page(1).size(100).build()).getResult().stream().filter(t -> ExecStatus.SUCCESS.name().equals(t.getLatestExecStatus())).count();
    OffsetDateTime since = OffsetDateTime.now().minusWeeks(1);
    if (count == 0) {
        UserCR userCR = UserITCase.getUniqueSample("purge@syncope.org");
        userCR.getResources().add(RESOURCE_NAME_WS1);
        UserTO userTO = createUser(userCR).getEntity();
        assertNotNull(userTO);
