        if (resourceConnector != null && property != null) {
            property.getValues().clear();
            property.getValues().add(Boolean.FALSE);
            CONNECTOR_SERVICE.update(resourceConnector);
        }
        if (user != null) {
            deleteUser(user.getKey());
        }
    }
}

