    assertFalse(USER_SERVICE.read("74cd8ece-715a-44a4-a736-e17b46c4e7e6").getResources().contains(RESOURCE_NAME_TESTDB2));
    assertFalse(USER_SERVICE.read("b3cbc78d-32e6-4bd4-92e0-bbe07566a2ee").getResources().contains(RESOURCE_NAME_TESTDB2));
