    jdbcTemplate.update("INSERT INTO TESTPRINTER (id, printername, location, deleted, lastmodification) VALUES (?,?,?,?,?)", printer.getKey(), printer.getName(), "Nowhere", false, new Date());
    // 3. verify reconciliation status
