@Test
public void updateUser() {
    SCIM_CONF_SERVICE.set(CONF);
    SCIMUser user = getSampleUser(UUID.randomUUID().toString(), List.of(Resource.User.schema()));
    Response response = webClient().path("Users").post(user);
    assertEquals(Response.Status.CREATED.getStatusCode(), response.getStatus());
    user = response.readEntity(SCIMUser.class);
    assertNotNull(user.getId());
    assertNull(user.getNickName());
    assertTrue(user.isActive());
    // 1. update no path, add value and suspend
    String body = "{" + "  \"schemas\":[\"urn:ietf:params:scim:api:messages:2.0:PatchOp\"]," + "  \"Operations\": [" + "    {" + "      \"op\": \"add\"," + "      \"value\": {" + "        \"nickName\": \"" + user.getUserName() + "\"," + "        \"active\": false" + "      }" + "    }" + "  ]" + "}";
    response = webClient().path("Users").path(user.getId()).invoke(HttpMethod.PATCH, body);
    assertEquals(Response.Status.OK.getStatusCode(), response.getStatus());
    user = response.readEntity(SCIMUser.class);
    assertEquals(user.getUserName(), user.getNickName());
    assertFalse(user.isActive());
    // 2. update with path, reactivate
    body = "{" + "\"schemas\":[\"urn:ietf:params:scim:api:messages:2.0:PatchOp\"]," + "\"Operations\":[{" + "\"op\":\"Replace\"," + "\"path\":\"active\"," + "\"value\":true" + "}]" + "}";
    response = webClient().path("Users").path(user.getId()).invoke(HttpMethod.PATCH, body);
    assertEquals(Response.Status.OK.getStatusCode(), response.getStatus());
    user = response.readEntity(SCIMUser.class);
    assertTrue(user.isActive());
    // 3. update with path, replace simple value
    assertNotEquals("newSurname", user.getName().getFamilyName());
    body = "{" + "\"schemas\":[\"urn:ietf:params:scim:api:messages:2.0:PatchOp\"]," + "\"Operations\":[" + "{" + "\"op\":\"Replace\"," + "\"path\":\"name.familyName\"," + "\"value\":\"newSurname\"" + "}," + "{" + "\"op\":\"remove\"," + "\"path\":\"nickName\"" + "}" + "]" + "}";
    response = webClient().path("Users").path(user.getId()).invoke(HttpMethod.PATCH, body);
    assertEquals(Response.Status.OK.getStatusCode(), response.getStatus());
    user = response.readEntity(SCIMUser.class);
    assertEquals("newSurname", user.getName().getFamilyName());
    assertNull(user.getNickName());
    // 4. update with path, replace complex value
    String newMail = UUID.randomUUID() + "@syncope.apache.org";
    assertNotEquals(newMail, user.getEmails().stream().filter(v -> "work".equals(v.getType())).findFirst().get().getValue());
    body = "{" + "     \"schemas\": [\"urn:ietf:params:scim:api:messages:2.0:PatchOp\"]," + "     \"Operations\": [{" + "       \"op\":\"replace\"," + "       \"path\":\"emails[type eq \\\"work\\\"]\"," + "       \"value\":" + "       {" + "         \"type\": \"work\"," + "         \"value\": \"" + newMail + "\"," + "         \"primary\": true" + "       }" + "     }]" + "   }";
    response = webClient().path("Users").path(user.getId()).invoke(HttpMethod.PATCH, body);
    assertEquals(Response.Status.OK.getStatusCode(), response.getStatus());
    user = response.readEntity(SCIMUser.class);
    assertEquals(newMail, user.getEmails().stream().filter(v -> "work".equals(v.getType())).findFirst().get().getValue());
    // 5. update with path, filter and sub
    newMail = "verycomplex" + UUID.randomUUID() + "@syncope.apache.org";
    body = "{" + "     \"schemas\": [\"urn:ietf:params:scim:api:messages:2.0:PatchOp\"]," + "     \"Operations\": [{" + "       \"op\":\"replace\"," + "       \"path\":\"emails[type eq \\\"work\\\"].value\"," + "       \"value\":\"" + newMail + "\"" + "     }]" + "   }";
    response = webClient().path("Users").path(user.getId()).invoke(HttpMethod.PATCH, body);
    assertEquals(Response.Status.OK.getStatusCode(), response.getStatus());
    user = response.readEntity(SCIMUser.class);
    assertEquals(newMail, user.getEmails().stream().filter(v -> "work".equals(v.getType())).findFirst().get().getValue());
    // 6. remove with path and filter
    body = "{" + "     \"schemas\": [\"urn:ietf:params:scim:api:messages:2.0:PatchOp\"]," + "     \"Operations\": [{" + "       \"op\":\"remove\"," + "       \"path\":\"emails[type eq \\\"home\\\"]\"" + "     }]" + "   }";
    response = webClient().path("Users").path(user.getId()).invoke(HttpMethod.PATCH, body);
    assertEquals(Response.Status.OK.getStatusCode(), response.getStatus());
    user = response.readEntity(SCIMUser.class);
    assertTrue(user.getEmails().stream().noneMatch(v -> "home".equals(v.getType())));
    // 7. update with path, update password
    body = "{" + "\"schemas\":[\"urn:ietf:params:scim:api:messages:2.0:PatchOp\"]," + "\"Operations\":[{" + "\"op\":\"replace\"," + "\"path\":\"password\"," + "\"value\":\"Password123!\"" + "}]" + "}";
    response = webClient().path("Users").path(user.getId()).header(RESTHeaders.PREFER, Preference.RETURN_NO_CONTENT).invoke(HttpMethod.PATCH, body);
    assertEquals(Response.Status.NO_CONTENT.getStatusCode(), response.getStatus());
    assertFalse(response.hasEntity());
}

