@Test
public void updateGroup() {
    SCIM_CONF_SERVICE.set(CONF);
    SCIMGroup group = new SCIMGroup(null, List.of(Resource.Group.schema()), null, UUID.randomUUID().toString());
    group.getMembers().add(new Member("74cd8ece-715a-44a4-a736-e17b46c4e7e6", null, null));
    group.getMembers().add(new Member("1417acbe-cbf6-4277-9372-e75e04f97000", null, null));
    Response response = webClient().path("Groups").post(group);
    assertEquals(Response.Status.CREATED.getStatusCode(), response.getStatus());
    group = response.readEntity(SCIMGroup.class);
    assertNotNull(group.getId());
    assertNull(group.getExternalId());
    assertEquals(2, group.getMembers().size());
    // 1. update with path, add value
    String body = "{" + "\"schemas\":[\"urn:ietf:params:scim:api:messages:2.0:PatchOp\"]," + "\"Operations\":[{" + "\"op\":\"Add\"," + "\"path\":\"externalId\"," + "\"value\":\"" + group.getId() + "\"" + "}]" + "}";
    response = webClient().path("Groups").path(group.getId()).invoke(HttpMethod.PATCH, body);
    assertEquals(Response.Status.OK.getStatusCode(), response.getStatus());
    group = response.readEntity(SCIMGroup.class);
    assertEquals(group.getId(), group.getExternalId());
    // 2. add member, remove member, remove attribute
    body = "{" + "\"schemas\":[\"urn:ietf:params:scim:api:messages:2.0:PatchOp\"]," + "\"Operations\":[" + "{" + "\"op\":\"Add\"," + "\"path\":\"members\"," + "\"value\":[{" + "\"value\":\"b3cbc78d-32e6-4bd4-92e0-bbe07566a2ee\"}]" + "}," + "{" + "\"op\":\"remove\"," + "\"path\":\"members[value eq \\\"74cd8ece-715a-44a4-a736-e17b46c4e7e6\\\"]\"" + "}," + "{" + "\"op\":\"remove\"," + "\"path\":\"externalId\"" + "}" + "]" + "}";
    response = webClient().path("Groups").path(group.getId()).invoke(HttpMethod.PATCH, body);
    assertEquals(Response.Status.OK.getStatusCode(), response.getStatus());
    group = response.readEntity(SCIMGroup.class);
    assertEquals(2, group.getMembers().size());
    assertTrue(group.getMembers().stream().anyMatch(m -> "b3cbc78d-32e6-4bd4-92e0-bbe07566a2ee".equals(m.getValue())));
    assertTrue(group.getMembers().stream().anyMatch(m -> "1417acbe-cbf6-4277-9372-e75e04f97000".equals(m.getValue())));
    assertNull(group.getExternalId());
    // 3. remove all members
    body = "{" + "\"schemas\":[\"urn:ietf:params:scim:api:messages:2.0:PatchOp\"]," + "\"Operations\":[" + "{" + "\"op\":\"remove\"," + "\"path\":\"members\"" + "}" + "]" + "}";
    response = webClient().path("Groups").path(group.getId()).invoke(HttpMethod.PATCH, body);
    assertEquals(Response.Status.OK.getStatusCode(), response.getStatus());
    group = response.readEntity(SCIMGroup.class);
    assertTrue(group.getMembers().isEmpty());
    // 4. add member
    body = "{" + "\"schemas\":[\"urn:ietf:params:scim:api:messages:2.0:PatchOp\"]," + "\"Operations\":[" + "{" + "\"op\":\"Add\"," + "\"path\":\"members\"," + "\"value\":[{" + "\"value\":\"b3cbc78d-32e6-4bd4-92e0-bbe07566a2ee\"}]" + "}" + "]" + "}";
    response = webClient().path("Groups").path(group.getId()).header(RESTHeaders.PREFER, Preference.RETURN_NO_CONTENT).invoke(HttpMethod.PATCH, body);
    assertEquals(Response.Status.NO_CONTENT.getStatusCode(), response.getStatus());
    assertFalse(response.hasEntity());
}

