    matches = RESOURCE_SERVICE.searchConnObjects(RESOURCE_NAME_LDAP, AnyTypeKind.USER.name(), new ConnObjectTOQuery.Builder().size(100).fiql(SyncopeClient.getConnObjectTOFiqlSearchConditionBuilder().is("mail").equalTo("*@syncope.apache.org").query()).build());
    assertTrue(matches.getResult().stream().anyMatch(connObj -> connObj.getAttr("cn").orElseThrow().getValues().contains("pullFromLDAP")));
    matches = RESOURCE_SERVICE.searchConnObjects(RESOURCE_NAME_LDAP, AnyTypeKind.USER.name(), new ConnObjectTOQuery.Builder().size(100).fiql(SyncopeClient.getConnObjectTOFiqlSearchConditionBuilder().is("givenName").equalToIgnoreCase("pullfromldap").query()).build());
