@Test
void liveSync() throws LDAPException {
    assumeThatCollection(System.getProperties().keySet()).anyMatch("OPENLDAP_IP"::equals);
    // 0. complete the predefined test users with missing attributes
    execOnOpenLDAP(ldapConn -> {
        ldapConn.modify("cn=user01,ou=People,o=isp", new Modification(ModificationType.ADD, "mail", "user01@syncope.apache.org"), new Modification(ModificationType.ADD, "givenName", "User01"));
        ldapConn.modify("cn=user02,ou=People,o=isp", new Modification(ModificationType.ADD, "mail", "user02@syncope.apache.org"), new Modification(ModificationType.ADD, "givenName", "User02"));
    });
    // 1. create and execute the live sync task
    LiveSyncTaskTO task = new LiveSyncTaskTO();
    task.setName("OpenLDAP SyncRepl");
    task.setDestinationRealm(SyncopeConstants.ROOT_REALM);
    task.setResource(RESOURCE_NAME_OPENLDAP);
    task.setLiveSyncDeltaMapper(SyncReplLiveSyncDeltaMapper.class.getSimpleName());
    task.getActions().add(SyncReplInboundActions.class.getSimpleName());
    task.getActions().add(LDAPMembershipPullActions.class.getSimpleName());
    task.setPerformCreate(true);
    task.setPerformUpdate(true);
    task.setPerformDelete(true);
    Response response = TASK_SERVICE.create(TaskType.LIVE_SYNC, task);
    LiveSyncTaskTO actual = getObject(response.getLocation(), TaskService.class, LiveSyncTaskTO.class);
    assertNotNull(actual);
    task = TASK_SERVICE.read(TaskType.LIVE_SYNC, actual.getKey(), true);
    assertNotNull(task);
    assertEquals(actual.getKey(), task.getKey());
    assertNotNull(actual.getJobDelegate());
    assertEquals(actual.getLiveSyncDeltaMapper(), task.getLiveSyncDeltaMapper());
    TASK_SERVICE.execute(new ExecSpecs.Builder().key(task.getKey()).build());
    try {
        // 2. check preexisting
        List<GroupTO> pregroups = await().atMost(MAX_WAIT_SECONDS, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).until(() -> {
            try {
                return GROUP_SERVICE.<GroupTO>search(new AnyQuery.Builder().fiql("name==readers").build()).getResult();
            } catch (SyncopeClientException e) {
                return List.of();
            }
        }, match -> match.size() == 1);
        assertEquals(1, pregroups.size());
        List<UserTO> preusers = await().atMost(MAX_WAIT_SECONDS, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).until(() -> {
            try {
                return USER_SERVICE.<UserTO>search(new AnyQuery.Builder().fiql("username==user0*").build()).getResult();
            } catch (SyncopeClientException e) {
                return List.of();
            }
        }, match -> match.size() == 2);
        assertEquals(2, preusers.size());
        assertTrue(preusers.stream().anyMatch(u -> "user01".equals(u.getUsername()) && "user01@syncope.apache.org".equals(u.getPlainAttr("email").orElseThrow().getValues().getFirst())));
        assertTrue(preusers.stream().anyMatch(u -> "user02".equals(u.getUsername()) && "user02@syncope.apache.org".equals(u.getPlainAttr("email").orElseThrow().getValues().getFirst())));
        assertTrue(preusers.stream().allMatch(u -> u.getPlainAttr("userEntryUUID").isPresent()));
        assertTrue(preusers.stream().allMatch(u -> u.getMembership(pregroups.getFirst().getKey()).isPresent()));
        // 3. ldap update
        execOnOpenLDAP(ldapConn -> ldapConn.modify("cn=user01,ou=People,o=isp", new Modification(ModificationType.REPLACE, "mail", "user01_new@syncope.apache.org")));
        // 4. check that change is now in Syncope
        await().atMost(MAX_WAIT_SECONDS, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).until(() -> USER_SERVICE.read("user01").getPlainAttr("email").orElseThrow().getValues().getFirst(), "user01_new@syncope.apache.org"::equals);
        // 5. ldap create
        execOnOpenLDAP(ldapConn -> {
            List<Attribute> attrs = List.of(new Attribute("objectClass", "inetOrgPerson"), new Attribute("uid", "jdoe"), new Attribute("sn", "Doe"), new Attribute("givenName", "John"), new Attribute("cn", "John Doe"), new Attribute("mail", "john.doe@syncope.apache.org"));
            ldapConn.add(new AddRequest("uid=jdoe,ou=People,o=isp", attrs));
        });
        // 6. check that the new user is now in Syncope
        await().atMost(MAX_WAIT_SECONDS, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).until(() -> {
            try {
                return USER_SERVICE.read("jdoe");
            } catch (SyncopeClientException e) {
                return null;
            }
        }, jdoe -> jdoe.getPlainAttr("userEntryUUID").isPresent());
        // 7. ldap delete
        execOnOpenLDAP(ldapConn -> ldapConn.delete("uid=jdoe,ou=People,o=isp"));
        // 8. check that the new user was removed from Syncope
        await().atMost(MAX_WAIT_SECONDS, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).failFast(() -> USER_SERVICE.read("jdoe"));
    } finally {
        // finally stop live syncing
        TASK_SERVICE.actionJob(task.getKey(), JobAction.STOP);
    }
}

@Test
public void issue186() {
    // 1. create an user with strict mandatory attributes only
    UserCR userCR = new UserCR();
    userCR.setRealm(SyncopeConstants.ROOT_REALM);
    String userId = getUUIDString() + "issue186@syncope.apache.org";
    userCR.setUsername(userId);
    userCR.setPassword("password123");
    userCR.getPlainAttrs().add(attr("userId", userId));
    userCR.getPlainAttrs().add(attr("fullname", userId));
    userCR.getPlainAttrs().add(attr("surname", userId));
    UserTO userTO = createUser(userCR).getEntity();
    assertNotNull(userTO);
    assertTrue(userTO.getResources().isEmpty());
    // 2. update assigning a resource forcing mandatory constraints: must fail with RequiredValuesMissing
    UserUR userUR = new UserUR.Builder(userTO.getKey()).password(new PasswordPatch.Builder().value("newPassword123").build()).resource(new StringPatchItem.Builder().operation(PatchOperation.ADD_REPLACE).value(RESOURCE_NAME_WS2).build()).build();
    try {
        userTO = updateUser(userUR).getEntity();
        fail("This should not happen");
    } catch (SyncopeClientException e) {
        assertEquals(ClientExceptionType.RequiredValuesMissing, e.getType());
    }
    // 3. update assigning a resource NOT forcing mandatory constraints
    // AND priority: must fail with PropagationException
    userUR = new UserUR();
    userUR.setKey(userTO.getKey());
    userUR.setPassword(new PasswordPatch.Builder().value("newPassword123").build());
    userUR.getResources().add(new StringPatchItem.Builder().operation(PatchOperation.ADD_REPLACE).value(RESOURCE_NAME_WS1).build());
    ProvisioningResult<UserTO> result = updateUser(userUR);
    assertNotNull(result.getPropagationStatuses().getFirst().getFailureReason());
    userTO = result.getEntity();
    // 4. update assigning a resource NOT forcing mandatory constraints
    // BUT not priority: must succeed
    userUR = new UserUR();
    userUR.setKey(userTO.getKey());
    userUR.setPassword(new PasswordPatch.Builder().value("newPassword123456").build());
    userUR.getResources().add(new StringPatchItem.Builder().operation(PatchOperation.ADD_REPLACE).value(RESOURCE_NAME_CSV).build());
    updateUser(userUR);
}

