@Test
public void issueSYNCOPE391() {
    assumeFalse(IS_EXT_SEARCH_ENABLED);
    // 1. create user on Syncope with null password
    UserCR userCR = UserITCase.getUniqueSample("syncope391@syncope.apache.org");
    userCR.setPassword(null);
