@SuppressWarnings("unchecked")
@Test
public void verifyTaskRegistration() {
    // get task list
    List<PropagationTaskTO> tasks = TASK_SERVICE.<PropagationTaskTO>search(new TaskQuery.Builder(TaskType.PROPAGATION).page(1).size(1000).build()).getResult();
    assertFalse(tasks.isEmpty());
    String maxKey = tasks.stream().max(Comparator.comparing(PropagationTaskTO::getStart, Comparator.nullsLast(Comparator.naturalOrder()))).map(PropagationTaskTO::getKey).orElse(null);
    assertNotNull(maxKey);
    // --------------------------------------
    // Create operation
    // --------------------------------------
    UserCR userCR = getUniqueSample("t@p.mode");
    // add a membership
    userCR.getMemberships().add(new MembershipTO.Builder("f779c0d4-633b-4be5-8f57-32eb478a3ca5").build());
    // 1. create user
    UserTO userTO = createUser(userCR).getEntity();
    assertNotNull(userTO);
    // get the new task list
    tasks = TASK_SERVICE.<PropagationTaskTO>search(new TaskQuery.Builder(TaskType.PROPAGATION).page(1).size(1000).build()).getResult();
    assertFalse(tasks.isEmpty());
    String newMaxKey = tasks.stream().max(Comparator.comparing(PropagationTaskTO::getStart, Comparator.nullsLast(Comparator.naturalOrder()))).map(PropagationTaskTO::getKey).orElse(null);
    assertNotNull(newMaxKey);
    // default configuration for ws-target-resource2 during create:
    // only failed executions have to be registered
    // --> no more tasks/executions should be added
    assertEquals(newMaxKey, maxKey);
    // --------------------------------------
    // Update operation
    // --------------------------------------
    UserUR userUR = new UserUR();
    userUR.setKey(userTO.getKey());
    userUR.getPlainAttrs().add(attrAddReplacePatch("surname", "surname2"));
    userTO = updateUser(userUR).getEntity();
    assertNotNull(userTO);
    // get the new task list
    tasks = TASK_SERVICE.<PropagationTaskTO>search(new TaskQuery.Builder(TaskType.PROPAGATION).page(1).size(1000).build()).getResult();
    assertFalse(tasks.isEmpty());
    // default configuration for ws-target-resource2 during update:
    // all update executions have to be registered
    newMaxKey = tasks.stream().max(Comparator.comparing(PropagationTaskTO::getStart, Comparator.nullsLast(Comparator.naturalOrder()))).map(PropagationTaskTO::getKey).orElse(null);
    assertNotNull(newMaxKey);
    assertNotNull(TASK_SERVICE.read(TaskType.PROPAGATION, newMaxKey, false));
    // --------------------------------------
    // Delete operation
    // --------------------------------------
    USER_SERVICE.delete(userTO.getKey());
    // get the new task list
    tasks = TASK_SERVICE.<PropagationTaskTO>search(new TaskQuery.Builder(TaskType.PROPAGATION).page(1).size(1000).build()).getResult();
    assertFalse(tasks.isEmpty());
    maxKey = newMaxKey;
    newMaxKey = tasks.stream().max(Comparator.comparing(PropagationTaskTO::getStart, Comparator.nullsLast(Comparator.naturalOrder()))).map(PropagationTaskTO::getKey).orElse(null);
    assertNotNull(newMaxKey);
    // default configuration for ws-target-resource2: no delete executions have to be registered
    // --> no more tasks/executions should be added
    assertEquals(newMaxKey, maxKey);
}

