        try {
            JsonNode body = MAPPER.readTree(response.getResponseBody());
            assertTrue(body.has("customized"));
            assertTrue(body.get("customized").asBoolean());
        } catch (IOException e) {
            fail(e.getMessage(), e);
        }
    });
}

